/** En saison : acheté chez Agrifresh depuis moins de 4 semaines, ou (sans historique) pas classé « hors saison » dans StorePOS. Même règle que la V1. */
const SEUIL_J = 28;
export function enSaison(o) { const k = autoIll(o.lib); if (!k) return false; const d = HIST[k]; return d ? days(d) <= SEUIL_J : key(o.grp || '') !== 'HORS SAISON'; }
export const ILLUSTRATIONS = () => Object.keys(D.ill).sort((a, b) => (D.lab[a] || a).localeCompare(D.lab[b] || b)).map(k => [k, D.lab[k] || k]);
export const ORIGINES = () => Object.entries(D.flags).sort((a, b) => a[1][1].localeCompare(b[1][1])).map(([c, v]) => [c, v[1]]);
